CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_384( p_collection text, p_chashes text[], p_cross_collection boolean ) RETURNS TABLE( chash text, topic_id bigint, similarity double precision ) LANGUAGE plpgsql SECURITY INVOKER AS $fn$ #variable_conflict use_column BEGIN IF p_cross_collection THEN -- Sam's standing rule for this RDR: one fail-loud path for every -- stub-insert, nothing mints a catalog_collections row from a name -- any more. Post-nexus-ft04v.7, chunks_collection_fk already requires -- p_collection to be registered before any chunk can exist under it, -- so if the batch below finds rows at all, the row is guaranteed -- present -- this guard only ever fires on a genuinely absent -- registration (a caller naming a collection with zero chunks), and -- names the remedy instead of silently minting the row this branch -- used to stub-insert here. IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection ) THEN RAISE EXCEPTION 'assign_from_chashes_384: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
-- nexus-f3yxx: the LATERAL's recall settings, transaction-local. -- NOT a function-level SET clause: CREATE FUNCTION ... SET hnsw.* -- fails with 'permission denied to set parameter' for a -- non-superuser migration role when pgvector's library is not yet -- loaded in that session (hnsw.* is then an unknown placeholder), -- which is every production boot (candidate-migration leg, -- 2026-09-25). set_config is allowed to any role. is_local=true -- scopes it to this transaction, which since the rework is the -- cross pass alone. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true);
-- nexus-swam7: pin the ACCESS PATH itself, not just the ANN recall -- settings. At ef_search=400 the planner's own cost model prefers a -- per-chunk Seq Scan + top-N Sort over taxonomy_centroids until -- ~8,000 centroids/dim (T2 nexus/p02-hnsw-incremental-recall- -- 2026-09-25); below that, this pin is what makes the "measured -- equal to exact at ef400" claim (taxonomy-018's header) actually -- true, by forcing the HNSW index scan the recall claim assumes. -- Legal as a function-level SET (these are core GUCs, unlike -- hnsw.*), but kept as set_config for consistency with the two -- calls above -- see this changeset's own header for the full -- reasoning and the measurement that verified each pin's effect. PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_384 AS b_emb FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_384 IS NOT NULL ORDER BY ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, ct.topic_id AS m_topic_id, (1 - (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.collection = p_collection AND ct.embedding_384 IS NOT NULL WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $fn$;

