CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_1024( p_collection text, p_chashes text[], p_cross_collection boolean ) RETURNS TABLE( chash text, topic_id bigint, similarity double precision ) LANGUAGE plpgsql SECURITY INVOKER AS $fn$ #variable_conflict use_column BEGIN IF p_cross_collection THEN IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection ) THEN RAISE EXCEPTION 'assign_from_chashes_1024: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
